class URLHandler:
    SCHEME_SEPARATOR = "://"
    PATH_SEPARATOR = "/"
    QUERY_SEPARATOR = "?"
    FRAGMENT_SEPARATOR = "#"
    PARAM_SEPARATOR = "&"
    KEY_VALUE_SEPARATOR = "="

    def __init__(self, url):
        self._url = url

    @property
    def url(self):
        return self._url

    def _find_scheme_end(self):
        return self._url.find(self.SCHEME_SEPARATOR)

    def _get_url_without_scheme(self):
        scheme_end = self._find_scheme_end()
        if scheme_end != -1:
            return self._url[scheme_end + len(self.SCHEME_SEPARATOR):]
        return None

    def get_scheme(self):
        scheme_end = self._find_scheme_end()
        if scheme_end != -1:
            return self._url[:scheme_end]
        return None

    def get_host(self):
        url_without_scheme = self._get_url_without_scheme()
        if url_without_scheme is not None:
            host_end = url_without_scheme.find(self.PATH_SEPARATOR)
            if host_end != -1:
                return url_without_scheme[:host_end]
            return url_without_scheme
        return None

    def get_path(self):
        url_without_scheme = self._get_url_without_scheme()
        if url_without_scheme is not None:
            host_end = url_without_scheme.find(self.PATH_SEPARATOR)
            if host_end != -1:
                return url_without_scheme[host_end:]
        return None

    def get_query_params(self):
        query_start = self._url.find(self.QUERY_SEPARATOR)
        if query_start == -1:
            return None
        fragment_start = self._url.find(self.FRAGMENT_SEPARATOR)
        if fragment_start == -1:
            query_string = self._url[query_start + 1:]
        else:
            query_string = self._url[query_start + 1:fragment_start]

        params = {}
        if len(query_string) > 0:
            param_pairs = query_string.split(self.PARAM_SEPARATOR)
            for pair in param_pairs:
                key_value = pair.split(self.KEY_VALUE_SEPARATOR)
                if len(key_value) == 2:
                    key, value = key_value
                    params[key] = value
        return params

    def get_fragment(self):
        fragment_start = self._url.find(self.FRAGMENT_SEPARATOR)
        if fragment_start != -1:
            return self._url[fragment_start + 1:]
        return None
